draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw character
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();

  // draw arms and legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 20, H/2 + 35);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20, H/2 + 35);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 15, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 15, H/2 + 70);
  ctx.stroke();

  // draw food
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t), H/2 - 20, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2 - 40, 10, 0, 2*Math.PI);
  ctx.fill();
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.sin(t + Math.PI/2), H/2 - 60, 10, 0, 2*Math.PI);
  ctx.fill();

  // draw benefit text
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('Healthy Food', W/2, H/2 + 100);

  ctx.restore();
}
